"""Generate a synthetic transcript -> meeting-minutes dataset.

Provenance statement (important for the report)
-----------------------------------------------

**This dataset is synthetic.** It is generated by the code in this file from
hand-written templates. It is *not* collected from real meetings, and it must
not be described as a real-world dataset. The reason for generating rather than
collecting is that real meeting corpora either require licences and data
agreements (AMI, ICSI) or raise consent and privacy issues that are out of
scope for a college project.

What the generator does produce is *structurally realistic* data: transcripts
built from a scenario (a topic, a set of speakers, a set of decisions and
action items that were actually agreed), so that the expected extraction is
known exactly and cannot be ambiguous. That gives clean supervision for
fine-tuning and an unambiguous reference for evaluation.

What it does **not** have, and what the limitations section of the report must
say: real disfluencies, overlapping speech, ASR errors, false starts,
interruptions, or the messiness that a genuine Whisper transcript contains.
Models fine-tuned on this data will learn the task format well and should not
be expected to transfer to messy real audio without further work. A more
honest evaluation uses the AMI corpus, described in datasets/README.md.

Output format (one JSON object per line, JSONL):
    {
      "transcript": "...",
      "target": {"title": ..., "date": ..., ...},
      "meta": {"scenario_id": ..., "synthetic": true, ...}
    }

Usage:
    python training/prepare_dataset.py --split all
    python training/prepare_dataset.py --split all --seed 1234
"""

from __future__ import annotations

import argparse
import json
import random
from dataclasses import dataclass, field
from pathlib import Path

from app.schemas.extraction import NOT_SPECIFIED

# ---------------------------------------------------------------------------
# Scenario model
# ---------------------------------------------------------------------------


@dataclass
class Scenario:
    """One meeting scenario, from which a transcript and target are built."""

    scenario_id: str
    topic: str
    title: str
    speakers: list[str]
    overview: str
    agenda: list[str]
    decision_templates: list[tuple[str, str]]  # (spoken phrasing, extracted decision)
    actions: list[tuple[str, str, str]]  # (person, spoken phrasing, task)
    # Parallel to actions. Each entry is (spoken phrase including its
    # preposition, extracted value), or ("", NOT_SPECIFIED) for none.
    # Storing the whole spoken phrase avoids ungrammatical output such as
    # "on the end of the month".
    deadlines: list[tuple[str, str]]
    conclusion: str


@dataclass
class GeneratedExample:
    """A finished transcript and its expected extraction."""

    transcript: str
    target: dict
    meta: dict = field(default_factory=dict)


# ---------------------------------------------------------------------------
# Phrasing banks
# ---------------------------------------------------------------------------

# Openers and closers vary so the model does not key on one fixed sentence.
OPENERS = [
    "Good morning everyone, let's begin the {topic} meeting.",
    "Hi all, thanks for joining the {topic} call.",
    "Alright, let's get started with the {topic} discussion.",
    "Welcome everyone to the {topic} sync.",
]

AGENDA_INTROS = [
    "First item on the agenda is",
    "Let's start with",
    "The first thing to cover is",
]

AGENDA_REACTIONS = [
    "Okay, noted.",
    "Thanks for the update.",
    "Good, that sounds fine.",
    "Understood.",
    "Right.",
]

# How a speaker announces a decision. The extracted value is the clean
# statement of what was decided.
DECISION_FRAMES = [
    "The team decided to {decision}.",
    "We have decided to {decision}.",
    "Okay, so we agreed to {decision}.",
    "Let's go with {decision}.",
    "Everyone agreed that we should {decision}.",
    "The decision is to {decision}.",
]

CONCLUSION_FRAMES = [
    "So to conclude, {conclusion}",
    "To sum up, {conclusion}",
    "In summary, {conclusion}",
    "Alright, to wrap up, {conclusion}",
]

# Utterances that mention no deadline at all, so the target is "Not specified".
# A model trained only on deadline-bearing examples would learn to invent one,
# so these negative examples are essential rather than optional.
NO_DEADLINE_REMARKS = [
    "",
    "",
    "",
    " There is no deadline for that yet.",
    " No date has been set for that one.",
]


def _capitalise(text: str) -> str:
    return text[:1].upper() + text[1:] if text else text


