# ---------------------------------------------------------------------------
# Transcript construction
# ---------------------------------------------------------------------------


def build_transcript(scenario: Scenario, rng: random.Random) -> str:
    """Turn a scenario into a natural-looking transcript.

    The expected extraction is fully determined by the scenario, so the
    supervision is exact: nothing the generator writes is ambiguous between
    a discussion point and a decision.
    """
    parts: list[str] = []

    opener = rng.choice(OPENERS).format(topic=scenario.topic)
    parts.append(opener)

    speaker_cycle = _cycle(scenario.speakers, rng)

    # Agenda walk-through produces discussion points.
    for index, item in enumerate(scenario.agenda):
        intro = rng.choice(AGENDA_INTROS) if index == 0 else "Next, let's look at"
        speaker = next(speaker_cycle)
        parts.append(f"{intro} {item}.")
        responder = next(speaker_cycle)
        parts.append(f"{rng.choice(AGENDA_REACTIONS)} {responder} will walk us through the details.")

    # Decisions, stated explicitly.
    for decision_spoken, _ in scenario.decision_templates:
        frame = rng.choice(DECISION_FRAMES)
        parts.append(_capitalise(frame.format(decision=decision_spoken)))

    # Action items.
    for index, (person, spoken, _) in enumerate(scenario.actions):
        spoken_phrase = scenario.deadlines[index][0] if index < len(
            scenario.deadlines
        ) else ""
        if spoken_phrase:
            parts.append(f"{person} will {spoken} {spoken_phrase}.")
        else:
            remark = rng.choice(NO_DEADLINE_REMARKS)
            parts.append(f"{person} will {spoken}.{remark}")

    # Conclusion.
    parts.append(_capitalise(rng.choice(CONCLUSION_FRAMES).format(
        conclusion=scenario.conclusion)))

    return " ".join(parts)


def _cycle(items: list[str], rng: random.Random):
    """An infinite round-robin over a shuffled list of speakers."""
    pool = list(items)
    rng.shuffle(pool)
    index = 0
    while True:
        yield pool[index % len(pool)]
        index += 1


def build_target(scenario: Scenario) -> dict:
    """Build the expected extraction for a scenario."""
    action_items = []
    for index, (person, _, task) in enumerate(scenario.actions):
        deadline = (
            scenario.deadlines[index][1]
            if index < len(scenario.deadlines)
            else NOT_SPECIFIED
        )
        action_items.append(
            {
                "task": task,
                "responsible_person": person,
                "deadline": deadline,
            }
        )

    return {
        "title": scenario.title,
        "date": NOT_SPECIFIED,
        "time": NOT_SPECIFIED,
        "participants": list(scenario.speakers),
        "overview": scenario.overview,
        "discussion_points": list(scenario.agenda),
        "decisions": [d for _, d in scenario.decision_templates],
        "action_items": action_items,
        "conclusion": scenario.conclusion,
    }


def generate_examples(seed: int = 42, variants: int = 1) -> list[GeneratedExample]:
    """Generate ``variants`` paraphrases of each scenario.

    Phrasings vary with the seed so the dataset can be regenerated with
    different surface forms while the expected extraction stays identical.
    That is what makes a held-out split meaningful: same task, different
    wording. Paraphrasing also stops the model keying on one fixed sentence
    pattern, which is the main risk with so few scenarios.
    """
    examples: list[GeneratedExample] = []
    for variant in range(variants):
        rng = random.Random(seed + variant * 1000)
        for scenario in SCENARIOS:
            transcript = build_transcript(scenario, rng)
            examples.append(
                GeneratedExample(
                    transcript=transcript,
                    target=build_target(scenario),
                    meta={
                        "scenario_id": scenario.scenario_id,
                        "synthetic": True,
                        "variant": variant,
                        "seed": seed + variant * 1000,
                        "speakers": len(scenario.speakers),
                        "action_items": len(scenario.actions),
                        "decisions": len(scenario.decision_templates),
                    },
                )
            )
    return examples


# ---------------------------------------------------------------------------
# Splitting and writing
# ---------------------------------------------------------------------------


def split_examples(
    examples: list[GeneratedExample],
    *,
    train_ratio: float = 0.6,
    val_ratio: float = 0.2,
) -> dict[str, list[GeneratedExample]]:
    """Split examples into train/validation/test by **scenario**.

    Splitting by scenario rather than by example is essential. Variants of the
    same scenario share a transcript skeleton, so if one variant were in train
    and another in test the evaluation would partly measure memorisation rather
    than generalisation. Grouping keeps every variant of a scenario in exactly
    one split.

    With six scenarios this yields a small test set - a real limitation of the
    synthetic dataset, and one that must be stated in the report rather than
    papered over.
    """
    by_scenario: dict[str, list[GeneratedExample]] = {}
    for example in examples:
        by_scenario.setdefault(example.meta["scenario_id"], []).append(example)

    scenario_ids = sorted(by_scenario)
    total = len(scenario_ids)
    train_end = max(1, int(total * train_ratio))
    val_end = max(train_end + 1, int(total * (train_ratio + val_ratio)))

    splits = {
        "train": scenario_ids[:train_end],
        "validation": scenario_ids[train_end:val_end],
        "test": scenario_ids[val_end:],
    }
    return {
        name: [example for sid in ids for example in by_scenario[sid]]
        for name, ids in splits.items()
    }


def write_jsonl(path: Path, examples: list[GeneratedExample]) -> None:
    """Write examples as JSONL, one object per line."""
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as handle:
        for example in examples:
            handle.write(
                json.dumps(
                    {
                        "transcript": example.transcript,
                        "target": example.target,
                        "meta": example.meta,
                    },
                    ensure_ascii=False,
                )
                + "\n"
            )


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument(
        "--output-dir",
        type=Path,
        default=Path(__file__).resolve().parent.parent / "datasets" / "processed",
        help="Where to write the JSONL splits.",
    )
    parser.add_argument("--seed", type=int, default=42)
    parser.add_argument(
        "--variants",
        type=int,
        default=8,
        help="Paraphrases generated per scenario. Splits are grouped by "
             "scenario, so variants never leak across train and test.",
    )
    args = parser.parse_args()

    examples = generate_examples(seed=args.seed, variants=args.variants)
    splits = split_examples(examples)

    for name, items in splits.items():
        destination = args.output_dir / f"{name}.jsonl"
        write_jsonl(destination, items)
        print(f"{name:11} {len(items):2d} examples -> {destination}")

    print(
        f"\nTotal {len(examples)} synthetic examples from {len(SCENARIOS)} scenarios.\n"
        "NOTE: this data is generated, not collected from real meetings. "
        "Describe it as such in any write-up."
    )


if __name__ == "__main__":
    main()